sys_script.script:
var alertTriggered = false;
var alertMessages = [];

// Check Weight on Bit limits (typical range: 10,000 - 50,000 lbs)
if (current.wob && (current.wob < 5000 || current.wob > 60000)) {
    alertMessages.push('WOB out of safe range: ' + current.wob + ' lbs');
    alertTriggered = true;
}

// Check Rate of Penetration (typical range: 10 - 200 ft/hr)
if (current.rop && (current.rop < 1 || current.rop > 300)) {
    alertMessages.push('ROP unusual: ' + current.rop + ' ft/hr');
    alertTriggered = true;
}

// Check standpipe pressure (typical range: 1000 - 4000 psi)
if (current.standpipe_pressure && current.standpipe_pressure > 5000) {
    alertMessages.push('High standpipe pressure: ' + current.standpipe_pressure + ' psi');
    alertTriggered = true;
}

// Check for H2S presence
if (current.h2s_reading && current.h2s_reading > 10) {
    alertMessages.push('H2S detected: ' + current.h2s_reading + ' ppm - Safety protocol required');
    alertTriggered = true;
}

// Set alert status
current.alert_status = alertTriggered;

if (alertTriggered) {
    current.notes = (current.notes ? current.notes + '\n' : '') + 
                   'ALERTS: ' + alertMessages.join('; ');
    gs.addErrorMessage('Drilling parameter alerts generated - check readings');
}
